import{_ as e,o as s,c as t,a8 as i}from"./chunks/framework.CNIpabDg.js";const g=JSON.parse('{"title":"Experimental package format","description":"Exact current experimental XPK/TAR layout, Miniserde manifest limits, signed message and registry preview paths.","frontmatter":{"layout":"doc","docType":"reference","description":"Exact current experimental XPK/TAR layout, Miniserde manifest limits, signed message and registry preview paths."},"headers":[],"relativePath":"reference/package-format.md","filePath":"reference/package-format.md","lastUpdated":1793045410000}'),n={name:"reference/package-format.md"};function r(o,a,l,p,d,h){return s(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793045410000"},[...a[0]||(a[0]=[i(`<h1 id="experimental-package-format" tabindex="-1">Experimental package format <a class="header-anchor" href="#experimental-package-format" aria-label="Permalink to &quot;Experimental package format&quot;">​</a></h1><p>This page describes the <strong>implemented development prototype</strong> in <a href="https://github.com/xila-project/package_manager" target="_blank" rel="noreferrer"><code>Xila-Project/package_manager</code></a>, not a stable installer wire protocol. <strong>Do not assume the <code>.xpk</code> extension, manifest version 1, TAR framing or signature envelope will remain unchanged.</strong> The final decision is tracked in <a href="https://github.com/xila-project/core/issues/402" target="_blank" rel="noreferrer">Core #402</a>.</p><h2 id="archive-entries" tabindex="-1">Archive entries <a class="header-anchor" href="#archive-entries" aria-label="Permalink to &quot;Archive entries&quot;">​</a></h2><p>The host <code>xila-package-writer</code> emits a deterministic, uncompressed <strong>USTAR</strong> archive. Only ordinary files are allowed.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>calculator.xpk                 # experimental TAR profile</span></span>
<span class="line"><span>  .xila/manifest.json         # required FIRST entry, Miniserde JSON</span></span>
<span class="line"><span>  .xila/manifest.sig          # optional SECOND entry, raw 64-byte Ed25519 signature</span></span>
<span class="line"><span>  bin/calculator.wasm          # first manifest-declared payload</span></span>
<span class="line"><span>  share/icon.png               # second manifest-declared payload (if any)</span></span></code></pre></div><p>The optional signature is absent in <strong>unsigned development packages</strong>. Payload entries must follow the manifest&#39;s exact list and order. The writer fixes metadata such as mtime and uid/gid to zero and uses mode <code>0644</code>. It never emits directories, symlinks, compressed content, PAX or GNU long-name extensions.</p><p>The reader uses <code>tar-no-std</code> 0.5.0&#39;s full-archive slice API. It rejects unexpected/nonordinary archive entries, missing or reordered payloads, size/hash mismatches and unsupported paths. This is <strong>inspection</strong>, not installation. Its API does not accept a streaming reader and requires the whole archive in memory.</p><h2 id="package-manifest-json-not-contributor-toml" tabindex="-1">Package manifest (JSON, not contributor TOML) <a class="header-anchor" href="#package-manifest-json-not-contributor-toml" aria-label="Permalink to &quot;Package manifest (JSON, not contributor TOML)&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;format_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xila.calculator&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wasm32-wasip1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;minimum_xila_abi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;capabilities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bin/calculator.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12345</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;sha256&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This is a <strong>shape example</strong>, not a real digest or downloadable package. The <code>sha256</code> field is the lowercase hex digest of the <strong>uncompressed logical file bytes</strong>. There is currently no compression or alternate file type.</p><table tabindex="0"><thead><tr><th>Implemented field/constraint</th><th>Current bound or rule</th></tr></thead><tbody><tr><td>Manifest encoded bytes</td><td>Maximum <strong>65,536 bytes</strong></td></tr><tr><td>Number of payload files</td><td><strong>1–128</strong></td></tr><tr><td>Total declared file lengths</td><td>At most <strong>256 MiB</strong></td></tr><tr><td>Payload path</td><td>Relative, nonempty, at most <strong>200 bytes</strong>, no <code>.</code>, <code>..</code>, empty segments, controls, backslashes, absolute paths or reserved <code>.xila/</code></td></tr><tr><td>Writer TAR path</td><td>ASCII only, at most <strong>99 bytes</strong> (stricter than manifest validation)</td></tr><tr><td>Package name</td><td>Dotted lowercase/digit/dash segments, maximum <strong>96 bytes</strong></td></tr><tr><td>Version</td><td>Nonempty, maximum <strong>64 bytes</strong>, ASCII alphanumeric plus <code>.</code>, <code>+</code>, <code>-</code>; <strong>not</strong> a complete SemVer enforcement policy</td></tr><tr><td>Target</td><td>Nonempty, maximum <strong>64 bytes</strong>, ASCII alphanumeric, dash or underscore</td></tr><tr><td><code>minimum_xila_abi</code></td><td>Unsigned 32-bit field; no installer enforces it yet</td></tr><tr><td>Capabilities</td><td>At most <strong>32</strong> nonempty strings of at most <strong>64 bytes</strong>; requests <strong>do not grant permissions</strong></td></tr><tr><td>File hash</td><td>Exactly 64 lowercase hexadecimal characters</td></tr><tr><td>Signature</td><td>Optional raw <strong>64-byte</strong> Ed25519 signature stored as second entry</td></tr></tbody></table><p>Manifest parsing is <code>no_std + alloc</code> using <strong>Miniserde JSON</strong>, not an allocation-free parser. The reader uses <code>alloc</code> for the message buffer when verifying signatures. Current validation provides <strong>no dependency solver, path destination mapping, privilege policy, symlink installation or compression framing</strong>.</p><h2 id="exact-provisional-signing-statement" tabindex="-1">Exact provisional signing statement <a class="header-anchor" href="#exact-provisional-signing-statement" aria-label="Permalink to &quot;Exact provisional signing statement&quot;">​</a></h2><p>For a canonical serialized manifest JSON byte array <code>M</code>, the implementation constructs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>signed_message = ASCII(&quot;XILA-PACKAGE-MANIFEST-V1\\0&quot;)</span></span>
<span class="line"><span>              || LE_U32(byte_length(M))</span></span>
<span class="line"><span>              || M</span></span></code></pre></div><p>Here <code>\\0</code> means <strong>one zero byte</strong> and <code>LE_U32</code> is a four-byte <strong>little-endian</strong> length. Ordinary, strict Ed25519 verification checks the signature over these <strong>exact stored manifest bytes</strong>. The reader must not reserialize the JSON before verification.</p><p><code>xila-package-builder pack</code> accepts an optional <strong>externally prepared</strong> 64-byte signature file. For a signed package, it checks that the supplied JSON is in the writer&#39;s canonical serialization. The tool does <strong>not</strong> create or validate the signer&#39;s identity or key authorization. There is no production key-ID envelope, revocation or rollback protection. The exact statement remains provisional until #402 freezes it and provides independent golden vectors.</p><p>Use <code>xila_package_reader::inspect_unsigned(&amp;archive)</code> only for untrusted structural inspection, <strong>never as an install-time authorization check</strong>. <code>verify_signed(&amp;archive, &amp;trusted_public_key)</code> authenticates the manifest and then checks file hashes, but the caller must have established key trust separately.</p><h2 id="community-registry-declaration-and-output-different-schema" tabindex="-1">Community registry declaration and output: different schema <a class="header-anchor" href="#community-registry-declaration-and-output-different-schema" aria-label="Permalink to &quot;Community registry declaration and output: different schema&quot;">​</a></h2><p>The <a href="https://github.com/xila-project/registry" target="_blank" rel="noreferrer"><code>registry</code> repository</a> currently accepts a <strong>host-only TOML declaration</strong>, not the JSON manifest above:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">schema = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;community.weather&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">summary = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Weather application&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">license = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MIT&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/example/weather&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">artifacts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wasm32-wasip1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">minimum_xila_abi = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/example/weather/releases/download/v1.0.0/weather.xpk&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sha256 = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10240</span></span></code></pre></div><p>These are intentionally illustrative placeholders. Real submissions must provide verified immutable hashes, sizes, source provenance and external release URLs.</p><p>Declarations live under <code>packages/&lt;namespace&gt;/&lt;application&gt;/&lt;version&gt;.toml</code>, with strict SemVer 2.0 ordering (no build metadata), <strong>1–32 artifacts</strong> with distinct targets, HTTPS URLs and lowercase 64-character SHA-256 digests. Artifact size must be <strong>1–2,147,483,647 bytes</strong>; the current validator requires the URL&#39;s path to end in <code>.xpk</code>. Supported declaration fields are <code>schema</code>, <code>package</code> (name/version/summary/license/source/optional homepage) and <code>artifacts</code> (target/minimum_xila_abi/url/sha256/size).</p><p>The Python preview publisher emits:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_site/v1/registry.json                         # counts/description, NOT a global catalog</span></span>
<span class="line"><span>_site/v1/packages/community/weather.json       # one package&#39;s available versions</span></span></code></pre></div><p>The registry currently contains <strong>zero published package declarations</strong>. The example under <code>examples/</code> is not included in generated metadata. A published preview describes an artifact <strong>without downloading, hashing or authenticating it</strong>; the declared SHA-256 is simply validated for format. All JSON output is <strong>unsigned</strong>.</p><p>This contributor schema is distinct from the archive&#39;s canonical install-time manifest. A shared, authoritative signed publication schema is future work in <a href="https://github.com/xila-project/core/issues/492" target="_blank" rel="noreferrer">#492</a>; clients must not treat the preview as an authenticated repository.</p><h2 id="source-references" tabindex="-1">Source references <a class="header-anchor" href="#source-references" aria-label="Permalink to &quot;Source references&quot;">​</a></h2><ul><li><a href="https://github.com/xila-project/package_manager/blob/main/crates/manifest/src/lib.rs" target="_blank" rel="noreferrer">Manifest source</a> — fields, limits, encoding, provisional signed statement.</li><li><a href="https://github.com/xila-project/package_manager/blob/main/crates/reader/src/lib.rs" target="_blank" rel="noreferrer">TAR reader source</a> — <code>inspect_unsigned</code> and <code>verify_signed</code>.</li><li><a href="https://github.com/xila-project/package_manager/blob/main/crates/writer/src/lib.rs" target="_blank" rel="noreferrer">TAR writer source</a> — deterministic USTAR writer.</li><li><a href="https://github.com/xila-project/package_manager/blob/main/docs/package-container-proposal.md" target="_blank" rel="noreferrer">Container architecture proposal</a> — open alternatives and requirements.</li><li><a href="https://github.com/xila-project/registry/blob/main/tools/registry.py" target="_blank" rel="noreferrer">Registry validator</a> — TOML schema and static JSON generation.</li><li><a href="https://github.com/xila-project/registry/blob/main/docs/architecture.md" target="_blank" rel="noreferrer">Registry architecture</a> — planned authenticated publication model.</li></ul>`,29)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
